// adler32: the Adler-32 checksum of 8 MiB of generated bytes.

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let (mut a, mut b) = (1u32, 0u32);
    for &x in &data {
        a = (a + x as u32) % 65521;
        b = (b + a) % 65521;
    }
    println!("{}", b << 16 | a);
}
